namespace WinFormsApp2;
internal sealed class BackupSecurityForm:SessionForm
{
    protected override bool ShowNavigationTools=>false;
    private readonly TextBox status=new(){Multiline=true,ReadOnly=true,Dock=DockStyle.Fill,ScrollBars=ScrollBars.Vertical,AccessibleName="Yedek ve kurtarma durumu",TabIndex=1};
    private readonly NumericUpDown keep=new(){Minimum=2,Maximum=90,Value=14,Width=75,AccessibleName="Tutulacak şifreli yedek sayısı"};
    private VaultManagementService Service=>new(AppDatabase.ConnectionString,User);
    internal BackupSecurityForm(UserSession user)
    {
        Session=user;Text="Muhasebe — Güvenli yedek ve destek";ClientSize=new(920,650);Controls.Add(status);
        var actions=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true,Padding=new(10),TabIndex=0};
        void Command(string text,string operation){var button=new Button{Text=text,AutoSize=true};actions.Controls.Add(button);button.Click+=async(_,_)=>{if(IsOperationRunning)return;int count=(int)keep.Value;keep.Enabled=false;await RunChangeOperationAsync(ct=>Service.ExecuteAsync(new(operation,AuditContext.ValidateReason(AuditContext.Reason??""),count),ct),"Kasa işlemi tamamlandı.");await ReloadAsync();};}
        Command("Şifreli yedek oluştur","Backup");Command("Son yedeği doğrula","Verify");Command("Aynalamayı yeniden dene","RetryMirror");actions.Controls.Add(new Label{Text="Tutulacak şifreli yedek:",AutoSize=true,Padding=new(0,7,0,0)});actions.Controls.Add(keep);Command("Saklama sayısını kaydet","Retention");
        var support=new Button{Text="Güvenli tanı paketi kaydet…",AutoSize=true};actions.Controls.Add(support);support.Click+=async(_,_)=>{if(IsOperationRunning)return;using var d=new SaveFileDialog{Filter="ZIP tanı paketi|*.zip",FileName="AccountingApp-guvenli-tani.zip",AddExtension=true,DefaultExt="zip"};if(d.ShowDialog(this)==DialogResult.OK)await RunOperationAsync(ct=>new SupportPackageService(AppDatabase.ConnectionString,User).SaveAsync(d.FileName,ct),"Kişisel veri/log içermeyen tanı paketi kaydedildi.");};
        var key=new Button{Text="Kurtarma anahtarlarını nasıl yönetirim?",AutoSize=true};actions.Controls.Add(key);key.Click+=(_,_)=>MessageBox.Show(this,"Sunucu bilgisayarında, API'yi çalıştıran Windows hesabıyla paketteki AccountingApp.BackupRecovery.exe aracını kullanın. Araç anahtar dışa/içe aktarımı, döndürme ve arşiv çözme işlemlerini sağlar. Parola gizli istenir; komut satırına yazılmaz. .abkey dosyasını ve parolasını yedeklerden ayrı saklayın. Anahtarlar API üzerinden gönderilmez. Ayrıntılar YEDEK_VE_DESTEK_GUVENLIGI.md belgesindedir.","Sunucu anahtar yönetimi");
        Controls.Add(actions);var note=new Label{Dock=DockStyle.Bottom,AutoSize=true,Padding=new(10),Text="Şifreli yedekler kişisel veridir. Durum bilgisi kurtarma provası değildir. Doğrulama yedeği çözerek SQL VERIFYONLY çalıştırır, veritabanını geri yüklemez. Merkezi API dosya yolu veya geri yükleme komutu almaz. Aynalama hedefi sunucu bakım aracıyla belirlenir. Eski .bak dosyaları otomatik silinmez."};Controls.Add(note);SizeChanged+=(_,_)=>note.MaximumSize=new(Math.Max(1,ClientSize.Width-20),0);
        RefreshAction=ReloadAsync;Load+=async(_,_)=>await ReloadAsync();SessionRevoked+=(_,_)=>Close();PageRequested+=(_,_)=>Close();
    }
    protected override void OnLoad(EventArgs e){base.OnLoad(e);MinimumSize=LogicalToDeviceUnits(new Size(650,500));}
    protected override void RefreshEditState(){keep.Enabled=!IsOperationRunning;}
    private async Task ReloadAsync()=>await RunOperationAsync(async ct=>{var s=await Service.StatusAsync(ct);keep.Value=s.Keep;status.Text=$"Anahtar kullanılabilir: {(s.KeyAvailable?"Evet":"Hayır / henüz oluşturulmadı")}\r\nEtkin anahtar kimliği: {s.ActiveKeyId?.ToString("D")??"yok"}\r\nEtkin anahtarın son dışa aktarımı UTC: {s.KeyExportedUtc?.ToString("dd.MM.yyyy HH:mm")??"kayıt yok; kurtarma anahtarını ayrı yere dışa aktarın"}\r\nŞifreli arşiv sayısı (kimliği okunabilen): {s.ArchiveCount}\r\nSon doğrulanmış oluşturma kaydı UTC: {s.LastVerifiedUtc?.ToString("dd.MM.yyyy HH:mm")??"yok"}\r\nTutulacak şifreli yedek: {s.Keep}\r\nHarici aynalama: {(s.MirrorConfigured?"Seçilmiş":"Seçilmemiş")}\r\nSon başarılı aynalama kaydı UTC: {s.LastMirrorUtc?.ToString("dd.MM.yyyy HH:mm")??"yok"}\r\nAynalama: {s.MirrorState switch{"NotConfigured"=>"Yapılandırılmamış","RecordedSuccess"=>"Başarı kaydı var; yeniden deneme bütünlüğü kontrol eder","NeedsAttention"=>"Anahtar/arşiv durumunu inceleyin",_=>"Bekliyor / yeniden deneyin"}}\r\n\r\nKurtarma provası: doğrulanmış prova kaydı tutulmuyor. Anahtar, arşiv bütünlüğü ve SQL doğrulaması tam geri yükleme provası değildir.\r\n\r\nTanı paketi sürüm, şema uyumu ve genel kasa durumuyla sınırlıdır. Log, hesap/personel, TC, IBAN, dosya yolu, adres, bağlantı profili veya anahtar içermez.";});
}
